/** A private Bridge introduces a head literal distinct from its antecedent literal. */
final class ContextAuthorityDistinctConstant {
    static int checks;static final int WORK=64000000;
    static void require(boolean yes,String why){++checks;if(!yes)throw new AssertionError(why);}
    static ContextUniversalCandidate.Evaluation inspect(ContextSevenPremiseNativeWriteRunner.Fixture f,String text,int rounds)throws Exception{return f.db.qualifyUniversalProductionCandidate(f.root,text,1000,rounds,16,16,65536,1000000,WORK,500000,WORK);}
    static final class Expected {
        final Set<Source> locals=new HashSet<>(),authorities=new HashSet<>(),bridges=new HashSet<>();final boolean negativeQ,negativeOut,negative,nullary;Source deny;
        Expected(ContextProductionCandidate.Staged a,int bridgeCount,boolean negativeQ,boolean negativeOut,boolean negative,boolean nullary){
            this.negativeQ=negativeQ;this.negativeOut=negativeOut;this.negative=negative;this.nullary=nullary;
            for(Entry e:a.staged.primary)locals.add(e.source);
            for(org.kanger.ContextProductionNativeBinding.Snapshot cut:a.foreign)for(Entry e:cut.primary){Clause c=e.clauses.get(0);if(c.literals.size()==2&&c.literals.stream().anyMatch(l->l.predicate.equals("mid")&&l.positive!=negative)&&c.literals.stream().anyMatch(l->l.predicate.equals("out")&&l.positive==negativeOut))bridges.add(e.source);
                else if(c.literals.size()==1){Atom atom=c.literals.get(0);if(atom.predicate.equals("q")&&atom.positive!=negativeQ)authorities.add(e.source);else if(atom.predicate.equals("mid")&&atom.positive==negative)deny=e.source;}}
            require(locals.size()==2&&locals.contains(a.candidate)&&authorities.size()==3&&authorities.stream().map(s->s.context).distinct().count()==3&&bridges.size()==bridgeCount&&bridges.stream().map(s->s.context).distinct().count()==bridgeCount&&deny!=null,"whole two-source X, three independent q authorities, independent private bridges and deny");
        }
        Set<Source> set(Source... extra){Set<Source> s=new HashSet<>(locals);s.addAll(Arrays.asList(extra));return s;}
        Set<Set<Source>> pairs(){Set<Set<Source>> result=new HashSet<>();for(Source q:authorities)for(Source b:bridges)result.add(new HashSet<>(Arrays.asList(q,b)));return result;}
    }
    static final class Coordinates {
        final SemanticTermSnapshot x,y,z,head;final Source premise1;final List<SemanticTermSnapshot> q,mid;
        Coordinates(ContextProductionCandidate.Staged a,Expected e,boolean conflict){require(a.base.primary.size()==1,"exactly one original producer premise");premise1=a.staged.primary.stream().filter(row->row.clauses.get(0).literals.get(0).predicate.equals("p1")).findFirst().get().source;Atom premise=a.base.primary.get(0).clauses.get(0).literals.get(0);x=premise.arguments.get(0).value;Atom deny=a.foreign.stream().flatMap(c->c.primary.stream()).filter(row->row.source.equals(e.deny)).findFirst().get().clauses.get(0).literals.get(0);Atom bridge=a.foreign.stream().flatMap(c->c.primary.stream()).filter(row->e.bridges.contains(row.source)).findFirst().get().clauses.get(0).literals.stream().filter(l->l.predicate.equals("out")).findFirst().get();y=bridge.arguments.get(1).value;head=a.foreign.stream().flatMap(c->c.primary.stream()).filter(row->e.bridges.contains(row.source)).findFirst().get().clauses.get(0).literals.stream().filter(l->l.predicate.equals("mid")).findFirst().get().arguments.get(1).value;z=deny.arguments.get(0).value;require(premise.predicate.equals("p1")&&!premise.positive&&x!=null&&y!=null&&z!=null&&head!=null&&!x.semanticallyEquals(y)&&!x.semanticallyEquals(head)&&!y.semanticallyEquals(head)&&y.semanticallyEquals(z),"distinct fixed producer value, private input/head literals; Deny free value equals input literal");require(deny.arguments.size()==3&&deny.arguments.get(1).value.semanticallyEquals(head)&&deny.arguments.get(2).value.semanticallyEquals(conflict?x:y),"Deny changes only fixed second coordinate");q=Arrays.asList(x,y,z);mid=Arrays.asList(z,head,x);}


    }
    static boolean ground(Atom atom,List<SemanticTermSnapshot> target){if(atom.arguments.size()!=target.size())return false;for(int i=0;i<target.size();i++)if(atom.arguments.get(i).variable>=0||!atom.arguments.get(i).value.semanticallyEquals(target.get(i)))return false;return true;}
    static void units(ContextUniversalUnitRounds.Frontier f,String predicate,int depth,List<Set<Source>> expected,Coordinates c,boolean negative,boolean ground){Set<Set<Source>> actual=new HashSet<>();int count=0;for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1){Atom atom=row.clause.literals.get(0);if(!atom.predicate.equals(predicate))continue;++count;require(atom.positive!=negative&&atom.arguments.size()==3&&row.support.depth==depth&&actual.add(row.support.sources),"exact polarity, arity, whole support and cumulative depth");if(ground)require(row.clause.variables.isEmpty()&&ground(atom,c.q),"ground counterproduction instantiates both formerly independent free coordinates");else if(predicate.equals("out"))require(row.clause.variables.size()==2&&atom.arguments.get(0).variable<0&&atom.arguments.get(0).value.semanticallyEquals(c.x)&&atom.arguments.get(1).variable>=0&&atom.arguments.get(2).variable>=0&&atom.arguments.get(1).variable!=atom.arguments.get(2).variable,"out retains two independent free coordinates around exact fixed first value");else require(independent(row.clause,c),"mid retains the unconstrained last input coordinate and exact fixed second value");}require(count==expected.size()&&actual.equals(new HashSet<>(expected)),"all exact free-coordinate Source alternatives for "+predicate);}
    static boolean independent(Clause clause,Coordinates c){if(clause.variables.size()!=1||clause.literals.size()!=1)return false;Atom a=clause.literals.get(0);return a.arguments.size()==3&&a.arguments.get(0).variable>=0&&a.arguments.get(1).variable<0&&a.arguments.get(1).value.semanticallyEquals(c.head)&&a.arguments.get(2).variable<0&&a.arguments.get(2).value.semanticallyEquals(c.x);}
    static void displacedPremise(ContextUniversalUnitRounds.Frontier f,Expected e,Coordinates c){Set<Set<Source>> expected=new HashSet<>(),actual=new HashSet<>();for(Source donor:e.authorities)for(Source bridge:e.bridges){Set<Source> sources=e.set(donor,bridge,e.deny);require(sources.remove(c.premise1)&&sources.size()==4,"derived p1 needs candidate, q, Bridge and Deny, not original p1(1)");expected.add(sources);}int count=0;for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1&&row.clause.literals.get(0).predicate.equals("p1")){++count;Atom atom=row.clause.literals.get(0);require(atom.positive&&row.clause.variables.isEmpty()&&ground(atom,Arrays.asList(c.y))&&row.support.depth==3&&actual.add(row.support.sources),"compatible p1 at different first value retains exact sign, coordinate, cumulative depth and unique Source alternative");}require(count==6&&actual.equals(expected),"all six independently enumerated displaced-premise alternatives");}
    static void consistent(Result r,Expected e,Coordinates value){require(r.status==Status.CONSISTENT&&r.collision==null&&r.certificate!=null&&r.completedBarriers>=2,"nonmatching ground deny has a complete stable-family model");ContextUniversalFamilyModel.Certificate c=r.certificate;require(c.cuts.size()==7&&c.input.cuts.size()==7,"seven exact private cuts");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut cut:c.cuts){receipts.add(cut.receipt);models.add(cut.model);require(cut.receipt.verified&&cut.receipt.input==c.input&&cut.model.ledger==cut.receipt.closureStep.input,"model is bound to its exact private closure");}require(ContextUniversalFamilyModel.certify(c.input,receipts,models,16,65536,WORK).certified,"independent all-values certificate recheck");List<Set<Source>> out=new ArrayList<>(),mid=new ArrayList<>();for(Source donor:e.authorities){out.add(e.set(donor));for(Source bridge:e.bridges)mid.add(e.set(donor,bridge));}units(c.input,"out",2,out,value,e.negativeOut,false);units(c.input,"mid",3,mid,value,e.negative,false);displacedPremise(c.input,e,value);require(c.input.products.stream().filter(row->row.clause.literals.size()==1).count()==15,"exactly three out, six mid and six displaced p1 units; no raw donor import");}
    static void collision(Result r,Expected e,Coordinates value,boolean exactLocal){require(r.status==Status.COLLISION&&r.certificate==null&&r.completedBarriers==3&&r.collision.oppositions.size()==12,"twelve complete third-barrier oppositions");Map<Set<Source>,Set<String>> actual=new HashMap<>();Set<Set<Source>> expected=e.pairs();for(Proof p:r.collision.oppositions){require(p.contradiction&&p.dependsOnX&&p.conclusion==null&&p.support.depth==4&&p.left.literals.size()==1&&p.right.literals.size()==1,"whole sourced unit refutation at cumulative depth4");Atom l=p.left.literals.get(0),rr=p.right.literals.get(0);require(l.predicate.equals(rr.predicate)&&l.positive!=rr.positive,"opposite signed endpoint");if(l.predicate.equals("q")){Set<Integer> slots=new HashSet<>();for(Slot slot:l.arguments){require(slot.variable>=0,"original private donor remains universal");slots.add(slot.variable);}require(slots.size()==3&&l.positive!=e.negativeQ&&p.leftSupport.sources.stream().anyMatch(e.authorities::contains)&&ground(rr,value.q),"ground counter-q instantiates the private literal middle coordinate and independent last coordinate");}else require(l.predicate.equals("mid")&&ground(l,value.mid)&&l.positive==e.negative&&p.leftSupport.sources.contains(e.deny)&&independent(p.right,value),"ground Deny meets the projected diagonal mid schema");require(p.leftSupport.depth==0&&p.leftSupport.sources.size()==1&&p.rightSupport.depth==3&&p.rightSupport.sources.size()==4,"private origin against transported whole four-source support");Set<Source> local=new HashSet<>(),foreign=new HashSet<>();for(Source source:p.support.sources)(source.localX?local:foreign).add(source);Set<Source> pair=new HashSet<>(foreign);pair.remove(e.deny);require(p.support.sources.size()==5&&local.size()==2&&foreign.size()==3&&foreign.contains(e.deny)&&expected.contains(pair),"whole X plus exact donor, Bridge and Deny");if(exactLocal)require(local.equals(e.locals),"exact fresh local Sources");require(actual.computeIfAbsent(pair,k->new HashSet<>()).add(l.predicate),"no duplicate endpoint hides another route");}require(actual.keySet().equals(expected)&&actual.values().stream().allMatch(v->v.equals(new HashSet<>(Arrays.asList("q","mid")))),"all six independently enumerated source pairs at both endpoints");}
    static void barriers(ContextProductionCandidate.Staged a,Expected e,Coordinates value,boolean conflict){ContextUniversalUnitRounds.Frontier initial=ContextUniversalUnitRounds.start(a.staged,a.foreign,WORK);ContextUniversalUnitRounds.Barrier first=ContextUniversalUnitRounds.merge(initial,ContextUniversalAuthorityChain.pass(initial,16),16,WORK);require(first.status==ContextUniversalUnitRounds.Status.MERGED&&first.changed&&initial.products.isEmpty(),"immutable first barrier");List<Set<Source>> out=new ArrayList<>(),mid=new ArrayList<>(),counter=new ArrayList<>();for(Source donor:e.authorities){out.add(e.set(donor));for(Source bridge:e.bridges)mid.add(e.set(donor,bridge));}for(Source bridge:e.bridges)counter.add(e.set(bridge,e.deny));units(first.frontier,"out",2,out,value,e.negativeOut,false);int saved=first.frontier.products.size();require(first.frontier.products.stream().filter(row->row.clause.literals.size()==1).count()==3,"first barrier exports three partial out schemas");ContextUniversalUnitRounds.Barrier second=ContextUniversalUnitRounds.merge(first.frontier,ContextUniversalAuthorityChain.pass(first.frontier,16),16,WORK);require(second.status==ContextUniversalUnitRounds.Status.MERGED&&second.changed&&first.frontier.products.size()==saved,"immutable second barrier");units(second.frontier,"out",2,out,value,e.negativeOut,false);units(second.frontier,"mid",3,mid,value,e.negative,false);if(conflict)units(second.frontier,"q",3,counter,value,!e.negativeQ,true);require(second.frontier.products.stream().filter(row->row.clause.literals.size()==1).count()==(conflict?11:9),"exact second-barrier units");if(!conflict){int secondSaved=second.frontier.products.size();ContextUniversalUnitRounds.Barrier third=ContextUniversalUnitRounds.merge(second.frontier,ContextUniversalAuthorityChain.pass(second.frontier,16),16,WORK);require(third.status==ContextUniversalUnitRounds.Status.MERGED&&third.changed&&second.frontier.products.size()==secondSaved,"immutable third barrier exports valid displaced premise");units(third.frontier,"out",2,out,value,e.negativeOut,false);units(third.frontier,"mid",3,mid,value,e.negative,false);displacedPremise(third.frontier,e,value);require(third.frontier.products.stream().filter(row->row.clause.literals.size()==1).count()==15,"third barrier exactly three out, six independent mid and six displaced p1 units");}}
    static void caseOf(Path dir,String name,boolean reverse,boolean negative,boolean conflict,boolean nativePath,String text)throws Exception{
        Set<String> persisted;List<RevisionRef> pins;long settled;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,name)){
            require(f.root.compile("!~p1(1);",null,false),"one exact local premise assertion");List<String> names=new ArrayList<>(Arrays.asList("A1","A2","A3","Bridge1","Bridge2","Deny"));if(reverse)Collections.reverse(names);for(String target:names)f.db.connectContext(target);f.db.saveConnections(f.root);
            ContextProductionInventory baseline=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> initial=ContextSevenPremiseNativeWriteRunner.origins(baseline);pins=ContextSevenPremiseNativeWriteRunner.pins(f);long revision=f.db.getRevision();int rows=f.root.getRules().size();require(initial.size()==1&&pins.size()==6,"only one local primary fact and six saved pins");
            ContextUniversalCandidate.Evaluation diagnostic=inspect(f,text,16);require(diagnostic.status==(conflict?Status.COLLISION:Status.CONSISTENT),"exact partial-substitution verdict: "+diagnostic.reason);
            Expected expected=new Expected(diagnostic.artifact,2,negative,negative,negative,false);
            Coordinates value=new Coordinates(diagnostic.artifact,expected,conflict);
            Clause candidate=diagnostic.artifact.staged.primary.stream().filter(e->e.source.equals(diagnostic.artifact.candidate)).findFirst().get().clauses.get(0);
            require(candidate.variables.size()==3&&candidate.literals.size()==3,"whole candidate retains three independent variables and three literals");
            Map<String,Atom> atoms=new HashMap<>();for(Atom atom:candidate.literals)atoms.put(atom.predicate,atom);
            Atom q=atoms.get("q"),out=atoms.get("out");require(q.arguments.size()==3&&out.arguments.size()==3,"ternary endpoints");
            Set<Integer> variables=new HashSet<>();for(int i=0;i<3;i++){require(q.arguments.get(i).variable>=0&&q.arguments.get(i).variable==out.arguments.get(i).variable,"candidate coordinate identity");variables.add(q.arguments.get(i).variable);}require(variables.size()==3&&atoms.get("p1").arguments.get(0).variable==q.arguments.get(0).variable,"one fixed x premise leaves y/z independent and free");
            for(org.kanger.ContextProductionNativeBinding.Snapshot cut:diagnostic.artifact.foreign)for(Entry entry:cut.primary){Clause c=entry.clauses.get(0);if(expected.authorities.contains(entry.source)){Atom atom=c.literals.get(0);Set<Integer> slots=new HashSet<>();for(Slot slot:atom.arguments){require(slot.variable>=0,"universal private donor coordinate");slots.add(slot.variable);}require(c.variables.size()==3&&slots.size()==3,"three independent private donor coordinates");}if(expected.bridges.contains(entry.source)){Atom o=c.literals.stream().filter(l->l.predicate.equals("out")).findFirst().get(),m=c.literals.stream().filter(l->l.predicate.equals("mid")).findFirst().get();require(c.variables.size()==2&&o.arguments.size()==3&&m.arguments.size()==3&&o.arguments.get(0).variable>=0&&o.arguments.get(2).variable>=0&&o.arguments.get(0).variable!=o.arguments.get(2).variable&&o.arguments.get(1).variable<0&&o.arguments.get(1).value.semanticallyEquals(value.y)&&m.arguments.get(0).variable==o.arguments.get(2).variable&&m.arguments.get(1).variable<0&&m.arguments.get(1).value.semanticallyEquals(value.head)&&m.arguments.get(2).variable==o.arguments.get(0).variable,"whole Bridge keeps literal middle constant and exact distinct head literal and swapped free/fixed output slots");}}


            if(conflict)collision(diagnostic.qualification,expected,value,true);else consistent(diagnostic.qualification,expected,value);
            barriers(diagnostic.artifact,expected,value,conflict);
            ContextUniversalCandidate.Evaluation stopped=inspect(f,text,1);require(stopped.status==Status.INCOMPLETE&&stopped.qualification.certificate==null&&stopped.qualification.collision==null&&stopped.reason.contains("common round limit"),"one common round cannot certify or expose opposition prefix");
            require(f.db.getRevision()==revision&&f.root.getRules().size()==rows&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(baseline.fingerprint)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"diagnostics preserve exact physical parent and topology");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(text,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(conflict){require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified,"actual native conflict independently audited");require(failure.getFamilyAudit().verdict!=diagnostic.qualification,"native guard uses a fresh actual-child verdict");collision(failure.getFamilyAudit().verdict,expected,value,false);}else require(failure==null,"actual native consistent candidate accepted");}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,text,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(conflict?DB.ProductionWriteStatus.COLLISION:DB.ProductionWriteStatus.PUBLISHED),"fresh public writer reaches expected settlement: "+result.status+" / "+result.trial.reason);require(result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial,"historical diagnostic is not publication authority");require(result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"exact pretrial and physical settlement references");if(conflict){Expected fresh=new Expected(result.trial.artifact,2,negative,negative,negative,false);collision(result.trial.qualification,fresh,new Coordinates(result.trial.artifact,fresh,conflict),true);}else{require(result.audit.oppositions.isEmpty(),"consistent publication has no collision attribution");Expected fresh=new Expected(result.trial.artifact,2,negative,negative,negative,false);consistent(result.trial.qualification,fresh,new Coordinates(result.trial.artifact,fresh,conflict) );}}
            ContextProductionInventory current=ContextSevenPremiseNativeWriteRunner.inventory(f);persisted=ContextSevenPremiseNativeWriteRunner.origins(current);settled=f.db.getRevision();require(ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"publication/refusal retains exact pinned order");
            if(conflict)require(settled==revision&&f.root.getRules().size()==rows&&current.fingerprint.equals(baseline.fingerprint)&&persisted.equals(initial),"conflict refusal retains exact original physical theory");
            else{require(settled>revision&&current.primary.size()==2&&persisted.size()==2&&persisted.containsAll(initial),"only one new whole rule is durably published");ContextProductionNativeBinding.Result bound=ContextProductionNativeBinding.bind(f.root,current,WORK,500000);require(bound.bound&&bound.snapshot.primary.size()==2&&bound.snapshot.primary.stream().anyMatch(e->e.clauses.size()==1&&e.clauses.get(0).equivalent(candidate)),"actual published primary equals the requested universal candidate");require(bound.snapshot.primary.stream().allMatch(e->e.clauses.size()==1&&(e.clauses.get(0).equivalent(candidate)||(e.clauses.get(0).literals.size()==1&&!e.clauses.get(0).literals.get(0).positive&&e.clauses.get(0).literals.get(0).predicate.equals("p1")))),"only original premises and whole candidate, no private or derived primary import");}
            System.out.println("DISTINCT_CONSTANT conflict="+conflict+" negative="+negative+" reverse="+reverse+" native="+nativePath+" diagnosticBarriers="+diagnostic.qualification.completedBarriers+" primary="+current.primary.size());
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,name)){ContextProductionInventory inv=ContextSevenPremiseNativeWriteRunner.inventory(f);require(f.db.getRevision()>=settled&&inv.primary.size()==(conflict?1:2)&&ContextSevenPremiseNativeWriteRunner.origins(inv).equals(persisted)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"reopen retains exactly original premises plus optional candidate and all pins");}
    }
    static void run(boolean reverse,boolean negative,boolean conflict,String marker){try{Path dir=Files.createTempDirectory("authority-distinct-constant-");System.setProperty("user.home",dir.toString());String sign=negative?"~":"";for(String name:new String[]{"A1","A2","A3"})ContextAuthorityChain.create(dir,name,"!@x @y @z "+sign+"q(x,y,z);");for(String name:new String[]{"Bridge1","Bridge2"})ContextAuthorityChain.create(dir,name,"!@x @z "+sign+"out(x,9,z)->"+sign+"mid(z,2,x);");ContextAuthorityChain.create(dir,"Deny","!"+(negative?"":"~")+(conflict?"mid(9,2,1);":"mid(9,2,9);"));String text="!@x @y @z "+sign+"q(x,y,z)&&~p1(x)->"+sign+"out(x,y,z);";caseOf(dir,"Public",reverse,negative,conflict,false,text);caseOf(dir,"Native",reverse,negative,conflict,true,text);System.out.println(marker+" checks="+(checks+ContextAuthorityChain.checks));System.exit(0);}catch(Throwable failure){if(failure instanceof org.kanger.exception.StorageLifecycleException){org.kanger.exception.StorageLifecycleException storage=(org.kanger.exception.StorageLifecycleException)failure;System.out.println("LIFECYCLE "+storage.getCode());for(ContextQualification.CollisionWitness witness:storage.getCollisions())System.out.println("WITNESS "+witness.getLeft()+" <> "+witness.getRight());}failure.printStackTrace();System.exit(1);}}
}
